function all(){prep();stats();chips();run(true)}
function opts(sel){return ORD().map(i=>[C[i],i]).map(([c,i])=>'<option value="'+i+'"'+(i===sel?' selected':'')+'>'+esc(c)+'</option>').join('')}
const open=h=>{$('bx').innerHTML=h;$('md').classList.add('on')},close=()=>{$('md').classList.remove('on');galU=null};
